def fit(points):
    # unweighted NLS for v = Vmax*S/(Km+S); Vmax solved in closed form for each Km
    def sse_vmax(km):
        f = [s/(km+s) for s, _ in points]
        num = sum(fi*v for fi, (_, v) in zip(f, points))
        den = sum(fi*fi for fi in f)
        vm = num/den
        return vm, sum((v - vm*fi)**2 for fi, (_, v) in zip(f, points))
    lo, hi = math.log(1e-3), math.log(1e5)
    gr = (math.sqrt(5)-1)/2
    a, b = lo, hi
    c, d = b - gr*(b-a), a + gr*(b-a)
    fc, fd = sse_vmax(math.exp(c))[1], sse_vmax(math.exp(d))[1]
    for _ in range(300):
        if fc < fd:
            b, d, fd = d, c, fc
            c = b - gr*(b-a); fc = sse_vmax(math.exp(c))[1]
        else:
            a, c, fc = c, d, fd
            d = a + gr*(b-a); fd = sse_vmax(math.exp(d))[1]
    km = math.exp((a+b)/2)
    return sse_vmax(km)[0], km

def fit_km_fixed_vmax(points, vmax):
