    a, b = lo, hi
    c, d = b-gr*(b-a), a+gr*(b-a)
    fc, fd = sse(math.exp(c)), sse(math.exp(d))
    for _ in range(300):
        if fc < fd:
            b, d, fd = d, c, fc
            c = b-gr*(b-a); fc = sse(math.exp(c))
        else:
            a, c, fc = c, d, fd
            d = a+gr*(b-a); fd = sse(math.exp(d))
    return math.exp((a+b)/2)

